import { Buffer } from 'node:buffer';

const baseline =
  '';

export function makeJpeg(): Uint8Array<ArrayBuffer> {
  const tiny = Buffer.from(baseline, 'base64');
  const parts = [tiny.subarray(0, 2)];
  let remaining = 300 * 1024 - tiny.length;
  while (remaining > 0) {
    const size = Math.min(remaining, 65537);
    const segment = Buffer.alloc(size);
    segment[0] = 0xff;
    segment[1] = 0xfe;
    segment.writeUInt16BE(size - 2, 2);
    parts.push(segment);
    remaining -= size;
  }
  parts.push(tiny.subarray(2));
  return new Uint8Array(Buffer.concat(parts));
}
